style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
:root, html, body {
    background-image: url("https://i.imgur.com/WR4Okai.jpeg") !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-size: cover !important;
    background-color: black !important;
  }

  .container-main,
  #rbx-body,
  .content,
  .rbx-body,
  .container-fluid,
  .section,
  .page-content,
  .content-container,
  .site-background {
    background: transparent !important;
    background-image: none !important;
  }

  header, footer, nav, .navbar, .footer-container, .menu-container {
    background: #000 !important;
  }

  img, svg, .icon, .logo {
    background: none !important;
  }
}
